-- docs/fight_macro_catalog_draft.lua  (DRAFT, not loaded by the addon, not in the TOC)
-- Fight macro catalogue for every class x talent spec x PvE/PvP, built from composable layers.
-- Research 2026-11-18; see docs/FIGHT_MACRO_RESEARCH_2026-11-18.md for the reasoning and sources.
-- EVERYTHING here is verified = false: spell names, learn levels and racials come from Forever
-- community guides (codes below) or, where marked CL, from Classic Era and are unconfirmed on Forever.
--
-- Shape:
--   catalog[CLASS].learn[spell] = { level, source, spec }   spec = talent tree tag (nil = trainer, every spec)
--   catalog[CLASS].trees = { tree1, tree2, tree3 }          talent tab order 1..3 (how detection maps points)
--   catalog[CLASS].keys = { fight = 'Fight', ... }          macro names per key
--   catalog[CLASS].specs[spec][mode] = {
--     brackets = { [key] = { { from = level, slots = { { line, spells, kind, keep, why } } } } },  -- every level a key changes
--     macros   = { [key] = { [level] = { text = '...', chars = n } } } }                         -- printed at key levels
--   key: ranged and melee for every class (Gary 2026-11-18), plus heal / pet / react / utility where the class has one;
--   keys[key] gives the macro name. A slot is written in full (line, spells, kind, keep, why) the first time it appears
--   in a key; in later brackets the same slot is just its line text (a string).
--   Printed macros show the in-fight state: buff lines (kind = buff) are left out, as the live builder does
--   while the buff is up; with a buff missing, the builder adds its line and drops the highest keep to fit.
--   spec = 'levelling' (no talents yet) or a tree tag; mode = 'pve' | 'pvp'
--   kind: target | guard | control | buff | opener | once | cooldown | filler | reactive | utility | heal | pet
--   keep: lower = kept when the macro must shrink under 255 characters (same rule as HunterFight M:Body)
--   races[race] = { faction, abilities = { { name, active|passive, slot, why } }, priest = { ... } }
--   utility[CLASS] = class utility macros (Trap, Burst, Break, Recover) with counted text
-- Source codes: WT = warcrafttavern.com/forever/guides/<class>-leveling (spells by level table, read
--   2026-11-18); TB = addon/Outrider/Data/Talents.lua (wowhandbook.com builds, read 2026-11-16);
--   GD = level range from a Forever guide's rotation text; CL = Classic Era value, Forever unconfirmed;
--   WT/TB = WT lists it at that level, Talents.lua as a talent: either way the live builder only
--   writes what the spellbook knows.
-- Printed macros assume every spell up to that level is trained and the spec's talents taken by the
--   build; '!Shoot' assumes a wand is equipped; druid [form:1] = Bear, [form:3] = Cat (the live
--   builder takes the numbers from GetShapeshiftFormInfo). Priest macros use the Undead race layer.

